const { getState, rows } = options;
const { editableItems, grid } = getState();
const selectedRows = grid.selectedRows;
if (selectedRows.length === 0) {
	return { hidden: true };
}

const hidden = selectedRows.some((rowId) => {
	const relatedId = rows.get(rowId, 'related_id');
	return !editableItems.has(relatedId);
});

return { hidden };
